export function StickyScrollEffect({
  sticky = {{sticky}},
  offset = {{offset}},
  edge = "{{edge}}",
  accent = "{{accent}}",
}) {
  const rows = ["Row one", "Row two", "Row three", "Row four", "Row five", "Row six"];
  const headerStyle = { padding: "8px 12px", fontWeight: 700, fontSize: 13, color: "#241430", background: accent, position: sticky ? "sticky" : "static", [edge]: offset };
  return (
    <div style={{ width: "100%", maxWidth: 320, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ height: 130, overflowY: "auto", border: "1px solid #24143022", borderRadius: 12, background: "#FAF7F2" }}>
        <div style={headerStyle}>Section heading</div>
        {rows.map((r) => (
          <p key={r} style={{ margin: 0, padding: "10px 12px", borderTop: "1px solid #24143014" }}>{r}</p>
        ))}
      </div>
      <p style={{ margin: "8px 0 0" }}>Scroll the box &middot; header {sticky ? `pins to the ${edge}` : "scrolls away normally"}</p>
    </div>
  );
}
